import { notFound, ok, withHandler } from "@/lib/api";
import { requireRole, requireScheduleRunQuota } from "@/lib/auth/guards";
import { getDb } from "@/lib/db";
import { activateTimetable } from "@/lib/services/timetable";

export const dynamic = "force-dynamic";
export const maxDuration = 60;

// Spelled out instead of `RouteContext<"/api/timetable/versions/[id]/activate">`: that global is
// generated by `next dev`/`next build`, and CI typechecks before building.
type Context = { params: Promise<{ id: string }> };

/** Version ids look like `TT-0003`; anything else can't exist (and isn't echoed back). */
const VERSION_ID = /^TT-\d{1,9}$/;

/**
 * Admin: make a stored version the active timetable and re-run Spectra decisions for it.
 * `404 NOT_FOUND` for an unknown id, `409 STALE_VERSION` for a version built on another dataset,
 * `409 HARD_CONSTRAINT` (with the violations) when it no longer passes the hard rules,
 * `409 CONFLICT` while another run holds the lock, `429 RATE_LIMITED` after too many runs.
 */
export const POST = withHandler(async (request, context: Context) => {
  const user = await requireRole(request, "admin");
  const { id } = await context.params;
  if (!VERSION_ID.test(id))
    throw notFound("No timetable version with that id.");
  requireScheduleRunQuota(request, user);
  return ok(await activateTimetable(await getDb(), id, user.id));
});
